import{_ as t,o as i,c as e,ag as r}from"./chunks/framework.DHSXpJLs.js";const g=JSON.parse('{"title":"编辑与版本","description":"","frontmatter":{},"headers":[],"relativePath":"guide/editing.md","filePath":"guide/editing.md","lastUpdated":1790779354000}'),l={name:"guide/editing.md"};function o(s,a,n,d,p,c){return i(),e("div",null,[...a[0]||(a[0]=[r(`<h1 id="编辑与版本" tabindex="-1">编辑与版本 <a class="header-anchor" href="#编辑与版本" aria-label="Permalink to &quot;编辑与版本&quot;">​</a></h1><p>平台里所有修改都是改构建脚本。IFC 和 DXF 永远是脚本跑出来的产物，所以任何一次保存，背后一定是一次脚本变更。</p><p>本页讲设计师视角的模型与操作。端点契约见 <a href="/SourceAEC/reference/edit-api">IFC 编辑 API</a>，界面控件见<a href="/SourceAEC/guide/interface">界面使用</a>，AI 侧接入见 <a href="/SourceAEC/reference/ai">AI 接入</a>。</p><h2 id="核心概念-script-as-source" tabindex="-1">核心概念：script-as-source <a class="header-anchor" href="#核心概念-script-as-source" aria-label="Permalink to &quot;核心概念：script-as-source&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plan / design 草稿（可选，AI 构思辅助，不落版本）</span></span>
<span class="line"><span>   → 构建脚本 v{n}.py（唯一事实源：PARAMS + build()）</span></span>
<span class="line"><span>   → 沙箱执行 → IFC / DXF v{n}（派生物，可随脚本重建）</span></span></code></pre></div><p>三件事由此成立：</p><ul><li><strong>模型等于脚本</strong>。每个大版本保留完整的 <code>scripts/v{n}.py</code> 和定位信息 <code>v{n}.map.json</code>，产物文件只留最新一份；历史版本需要对比或下载时，从对应脚本重建。</li><li><strong>选中即定位</strong>。点构件能跳到生成它的那一行脚本，改完先试运行看效果，满意再保存成大版本。</li><li><strong>对比不做几何</strong>。分两层：脚本层面的文本 diff，加上构件属性层面的语义 diff。改几何就是改脚本，所以不需要几何对比。</li></ul><p>design JSON 只是个例外说明：它指 AI 起草阶段的草稿，不是模型的完整表示，<strong>不进版本、不参与 diff</strong>。与 IFC 一一对应的只有构建脚本，交付物永远是脚本。</p><h2 id="模型的两种形态" tabindex="-1">模型的两种形态 <a class="header-anchor" href="#模型的两种形态" aria-label="Permalink to &quot;模型的两种形态&quot;">​</a></h2><ul><li><strong>script-backed</strong>：模型有构建脚本，具备完整编辑能力——定位、参数表单、脚本编辑器、暂存、版本。</li><li><strong>plain</strong>：模型是外部上传的，没有脚本，只能查看和审查。让 AI 把它复现成脚本之后就变成 script-backed，见文末 bootstrap。</li></ul><h2 id="选中构件-定位脚本" tabindex="-1">选中构件，定位脚本 <a class="header-anchor" href="#选中构件-定位脚本" aria-label="Permalink to &quot;选中构件，定位脚本&quot;">​</a></h2><p>属性面板是只读的，要修改先选中构件，点<strong>定位脚本</strong>按钮：</p><ol><li>按 IFC GlobalId 查（DXF 侧按实体 key 查）。</li><li>命中后自动切到 Design 面板的脚本编辑器，光标落在生成这个构件的那一行并高亮。</li><li>查不到就保持只读。如果暂存脚本和定位信息对不上，会提示先运行一次脚本再定位。</li></ol><h2 id="两种改法" tabindex="-1">两种改法 <a class="header-anchor" href="#两种改法" aria-label="Permalink to &quot;两种改法&quot;">​</a></h2><p>Design 面板有两种模式：参数表单和脚本编辑器。定位结果里的 origin 标签决定用哪种：</p><ul><li><strong>origin 是 params</strong>：构件参数来自脚本头部的 PARAMS 块。在参数表单里改对应键的值，提交即可。</li><li><strong>origin 是 literal</strong>：参数是写死在调用行里的字面量。直接在脚本编辑器里改这一行，或者让 AI 调定向改写接口由服务端精确重写这个标量，保留原有格式和注释。</li><li><strong>origin 是 traced</strong>：参数是运行时算出来的，只能定位不能自动改写，请打开脚本编辑器手动改。</li></ul><h2 id="沙箱验证与暂存" tabindex="-1">沙箱验证与暂存 <a class="header-anchor" href="#沙箱验证与暂存" aria-label="Permalink to &quot;沙箱验证与暂存&quot;">​</a></h2><p>表单提交或脚本保存时，先做静态契约校验，不通过直接报 422，什么都不会被修改。通过后进入暂存区：最多保留 10 步，原子落盘，重启不丢，支持撤销和重做。</p><p>暂存之后有三个去向：</p><ul><li><strong>放弃</strong>：丢弃整条暂存链，不产生任何版本。</li><li><strong>试运行</strong>：在沙箱里执行暂存脚本，预览产物，不产生版本。</li><li><strong>保存版本</strong>：执行脚本生成 IFC 或 DXF，固化为大版本 v{n+1}。</li></ul><p>Design 面板在 xeokit、web-ifc、DXF 三条查看分支上完全一致，共用同一份数据和接口。</p><h2 id="大版本与回滚" tabindex="-1">大版本与回滚 <a class="header-anchor" href="#大版本与回滚" aria-label="Permalink to &quot;大版本与回滚&quot;">​</a></h2><p>大版本是用户或 AI 主动保存的检查点。脚本和定位 map 全量保留、成对快照，编号只增不改。产物文件只物化最新一份，历史版本 diff 或下载时从脚本重建，结果进缓存。</p><p>版本列表里可以对非当前版本<strong>回滚</strong>：恢复那版的脚本并重新执行。因为回滚走的是同一套链路，脚本和产物永远一致，不存在改了产物没改脚本的分叉。</p><p>AI 下次介入时拿到的输入是当前脚本加两层 diff 摘要，所以它的修改是增量式的，不是推倒重写。</p><h2 id="版本对比" tabindex="-1">版本对比 <a class="header-anchor" href="#版本对比" aria-label="Permalink to &quot;版本对比&quot;">​</a></h2><p>工具栏的 Diff 按钮打开对比面板：</p><ol><li>选 base 和 target。target 可以是某个版本，也可以是当前状态。</li><li>点对比。绿色是新增，黄色是修改，红色是删除。</li><li>点条目定位到构件；修改条目可以展开，看每个字段的旧值和新值。</li><li>点清除复位着色。</li></ol><p>对比按确定性 GlobalId 或实体 key 对齐，IFC 和 DXF 两侧逻辑相同。对比分三个粒度：</p><table tabindex="0"><thead><tr><th>层</th><th>对象</th><th>受众</th></tr></thead><tbody><tr><td>脚本文本 diff 加 PARAMS 键级变更</td><td><code>v{n-1}.py</code> 对 <code>v{n}.py</code>，以及暂存步之间</td><td>AI 的下一轮上下文；用户在脚本 diff 视图看</td></tr><tr><td>IFC 语义 diff，属性级 GlobalId 对齐</td><td>两个版本的 IFC</td><td>用户在 Diff 面板看</td></tr><tr><td>外部上传模型，按 GlobalId 做属性级对比</td><td>无脚本时的对比对象</td><td>用户</td></tr></tbody></table><h2 id="中途预览" tabindex="-1">中途预览 <a class="header-anchor" href="#中途预览" aria-label="Permalink to &quot;中途预览&quot;">​</a></h2><p>AI 或人在试运行成功后，保存版本之前就能看到中间结果：</p><ul><li>DXF 和 web-ifc 分支画布直接刷新，代价低。</li><li>xeokit 分支重转 XKT 比较慢，画布左上角出现「AI 中间结果 · 点击预览」角标，点击才重载。</li></ul><p>保存大版本后由提交完成事件驱动常规刷新。</p><h2 id="bootstrap-把上传的-ifc-变成脚本" tabindex="-1">bootstrap：把上传的 IFC 变成脚本 <a class="header-anchor" href="#bootstrap-把上传的-ifc-变成脚本" aria-label="Permalink to &quot;bootstrap：把上传的 IFC 变成脚本&quot;">​</a></h2><p>有 AI 参与时，上传 IFC 的意图是让它照着做一份：</p><ol><li>用户上传 IFC，此时是 plain 态，只能看。</li><li>AI 通过 MCP server 读取模型，用 aiifc skill 编写复现脚本。</li><li>首次暂存时平台自动把上传原件保存为 <code>bootstrap.ifc</code>。脚本经沙箱验证后保存为大版本 v1，模型转为 script-backed。</li><li>首次保存的响应里有 alignment 计数，也就是原件和生成结果之间的差异摘要，用它判断复现是否走样；对齐计算失败不影响保存本身。</li></ol>`,37)])])}const u=t(l,[["render",o]]);export{g as __pageData,u as default};
